describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 50 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 50 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 2000, costCents: 800 },
      ],
      1200,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for cart with 0 total weight", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
      ];
      expect(calc.computeShippingCents(lines, 200)).toBe(0);
    });

    it("selects first bracket for weight at lower boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
    });

    it("selects second bracket for weight just over first boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(500);
    });

    it("selects bracket at exact upper boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 1000)], 1000)).toBe(500);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(calc.computeShippingCents([makeLine("a", 2001)], 1000)).toBe(1200);
    });

    it("uses heaviest bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      expect(noOverflow.computeShippingCents([makeLine("a", 5000)], 1000)).toBe(500);
    });

    it("accounts for quantity in weight calculation", () => {
      // 3 items × 400g = 1200g → third bracket (upToGrams: 2000)
      expect(calc.computeShippingCents([makeLine("a", 400, 3)], 1000)).toBe(800);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 800 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      expect(unordered.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart line management", () => {
  it("add creates a new line", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantity for same product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add rejects non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add rejects negative unitPriceCents", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove returns true and removes existing product", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.updateQuantity("a", 3);
    expect(cart.itemCount).toBe(3);
  });

  it("updateQuantity with 0 removes the line", () => {
    const cart = new Cart();
    cart.add(productA, 5);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("nonexistent", 1)).toThrow();
  });

  it("updateQuantity rejects negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("clear removes all lines", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0].quantity).toBe(2);
    // Mutating snapshot doesn't affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    const t = cart.totals();
    expect(t.subtotalCents).toBe(4000);
  });

  it("applies discount then tax on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(500),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(280),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(productA, 3); // subtotal = 3000
    const t = cart.totals();

    expect(t.subtotalCents).toBe(3000);
    expect(t.discountCents).toBe(500);
    // tax should be called with discounted subtotal (2500)
    expect(tax.computeTaxCents).toHaveBeenCalledWith(2500, "US");
    expect(t.taxCents).toBe(280);
  });

  it("shipping receives discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(1000),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(599),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(productA, 3); // subtotal = 3000, discounted = 2000
    const t = cart.totals();

    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      2000,
    );
    expect(t.shippingCents).toBe(599);
  });

  it("clamps discount to [0, subtotal]", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1); // subtotal = 1000
    const t = cart.totals();
    expect(t.discountCents).toBe(1000); // clamped to subtotal
    expect(t.totalCents).toBe(0); // nothing left
  });

  it("clamps negative discount to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(64),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(productA, 1); // subtotal=1000, discounted=800
    const t = cart.totals();
    expect(t.totalCents).toBe(800 + 64 + 500);
  });

  it("uses configured region for tax", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("empty cart returns all zeros", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000, weightGrams: 200 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000, weightGrams: 500 };

describe("Cart.checkout()", () => {
  describe("price refresh", () => {
    it("refreshes prices via priceFetcher before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };

      const result = await cart.checkout({ priceFetcher });
      expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    });

    it("throws RangeError if fetcher returns negative price", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(-100),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("throws RangeError if fetcher returns non-integer price", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(10.5),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(RangeError);
    });

    it("propagates priceFetcher rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("fetch failed")),
      };

      await expect(cart.checkout({ priceFetcher })).rejects.toThrow("fetch failed");
    });
  });

  describe("inventory check", () => {
    it("passes when all items are available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };

      const result = await cart.checkout({ inventoryChecker });
      expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
      expect(result.totals.subtotalCents).toBe(2000);
    });

    it("throws InventoryError when item unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "out of stock",
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(5);
        expect(err.available).toBe(2);
        expect(err.message).toBe("out of stock");
      }
    });

    it("throws InventoryError on partial-stock denial (available: true but quantity insufficient)", async () => {
      const cart = new Cart();
      cart.add(productA, 10);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        expect(e).toBeInstanceOf(InventoryError);
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
        expect(err.requested).toBe(10);
        expect(err.available).toBe(3);
      }
    });

    it("first denial wins when multiple items fail", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);

      const inventoryChecker: InventoryChecker = {
        check: vi.fn()
          .mockResolvedValueOnce({ available: false, reason: "A out" })
          .mockResolvedValueOnce({ available: false, reason: "B out" }),
      };

      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (e) {
        const err = e as InventoryError;
        expect(err.productId).toBe("a");
      }
    });
  });

  describe("async tax provider", () => {
    it("uses asyncTaxProvider for tax computation", async () => {
      const cart = new Cart({ region: "US-CA" });
      cart.add(productA, 2); // subtotal = 2000

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.0875),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
      // tax = floor(2000 * 0.0875) = 175
      expect(result.totals.taxCents).toBe(175);
    });

    it("async tax is computed on discounted subtotal", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        region: "US",
      });
      cart.add(productA, 10); // subtotal=10000, discount=1000, discounted=9000

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };

      const result = await cart.checkout({ asyncTaxProvider });
      expect(result.totals.discountCents).toBe(1000);
      // tax = floor(9000 * 0.1) = 900
      expect(result.totals.taxCents).toBe(900);
    });

    it("propagates async tax provider rejection", async () => {
      const cart = new Cart();
      cart.add(productA, 1);

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
      };

      await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
        "rate service down",
      );
    });
  });

  describe("full pipeline integration", () => {
    it("price refresh → inventory → async tax → discount → shipping", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        shippingCalculator: new FlatShippingCalculator(500),
        region: "FR",
      });
      cart.add(productA, 2);
      cart.add(productB, 1);

      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn()
          .mockResolvedValueOnce(1200) // productA refreshed
          .mockResolvedValueOnce(2500), // productB refreshed
      };

      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };

      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2), // 20% FR VAT
      };

      const result = await cart.checkout({
        priceFetcher,
        inventoryChecker,
        asyncTaxProvider,
      });

      // subtotal = 1200*2 + 2500*1 = 4900
      expect(result.totals.subtotalCents).toBe(4900);
      // discount = floor(4900 * 20/100) = 980
      expect(result.totals.discountCents).toBe(980);
      // discounted = 4900 - 980 = 3920
      // tax = floor(3920 * 0.2) = 784
      expect(result.totals.taxCents).toBe(784);
      // shipping = 500 (flat)
      expect(result.totals.shippingCents).toBe(500);
      // total = 3920 + 784 + 500 = 5204
      expect(result.totals.totalCents).toBe(5204);
    });

    it("checkout without collaborators uses sync pipeline", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(1000);
      expect(result.totals.totalCents).toBe(1000);
      expect(result.lines).toHaveLength(1);
    });
  });
});

