toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity: number = 1,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("always returns 0", () => {
    expect(calc.computeShippingCents([makeLine("a", 500)], 5000)).toBe(0);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 100.5)).toThrow(RangeError);
    });

    it("accepts valid inputs", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
      expect(() => new FlatShippingCalculator(500, 5000)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flatCents for non-empty cart below threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 4999)).toBe(599);
    });

    it("returns 0 when subtotal meets freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds freeOver threshold", () => {
      const calc = new FlatShippingCalculator(599, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 10000)).toBe(0);
    });

    it("returns 0 for empty cart even without threshold", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns flatCents when no threshold configured", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 100)], 100)).toBe(599);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 50 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 50 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 2000, costCents: 800 },
      ],
      1200,
    );

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for cart with 0 total weight", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
      ];
      expect(calc.computeShippingCents(lines, 200)).toBe(0);
    });

    it("selects first bracket for weight at lower boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
    });

    it("selects second bracket for weight just over first boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(500);
    });

    it("selects bracket at exact upper boundary", () => {
      expect(calc.computeShippingCents([makeLine("a", 1000)], 1000)).toBe(500);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      expect(calc.computeShippingCents([makeLine("a", 2001)], 1000)).toBe(1200);
    });

    it("uses heaviest bracket cost when no overflow specified", () => {
      const noOverflow = new WeightBasedShippingCalculator([
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      expect(noOverflow.computeShippingCents([makeLine("a", 5000)], 1000)).toBe(500);
    });

    it("accounts for quantity in weight calculation", () => {
      // 3 items × 400g = 1200g → third bracket (upToGrams: 2000)
      expect(calc.computeShippingCents([makeLine("a", 400, 3)], 1000)).toBe(800);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = new WeightBasedShippingCalculator([
        { upToGrams: 2000, costCents: 800 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 500 },
      ]);
      expect(unordered.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
    });
  });
});

